const CODIGOS = ['128A', '05FK'];
const PREFIXO = 'RA';

const data = $input.first().json;

function formatBRL(v) {
  return 'R$ ' + Number(v).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function formatData(iso) {
  return iso.split('-').reverse().join('/');
}

function buildTable(rows, comDiasEmAberto) {
  const header = '<tr><th>Concessionaria</th><th>No Pedido</th><th>Lote</th><th>Data Integracao</th><th>Valor</th>' + (comDiasEmAberto ? '<th>Dias em Aberto</th>' : '') + '</tr>';
  const body = rows.map((r) => {
    return '<tr><td>' + r.codigo_concessionaria + '</td><td>' + r.numero_pedido + '</td><td>' + (r.lote || '-') + '</td><td>' + formatData(r.data_integracao) + '</td><td>' + formatBRL(r.valor) + '</td>' + (comDiasEmAberto ? '<td>' + r.dias_em_aberto + '</td>' : '') + '</tr>';
  }).join('');
  return '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;">' + header + body + '</table>';
}

const novos = (data.novos || []).filter((r) => CODIGOS.includes(r.codigo_concessionaria));
const atrasados = (data.atrasados || []).filter((r) => CODIGOS.includes(r.codigo_concessionaria));

let secoes = '';

if (novos.length) {
  secoes += '<h3>Pedidos novos hoje (' + novos.length + ')</h3>' + buildTable(novos, false);
}

if (atrasados.length) {
  secoes += '<h3>Pedidos em aberto atrasados (' + atrasados.length + ')</h3>' + buildTable(atrasados, true);
}

const hoje = new Date().toLocaleDateString('pt-BR');
const corpoHtml = '<p>Resumo da checagem de comissoes Hapvida (' + CODIGOS.join(', ') + ') em ' + hoje + ':</p>' + secoes;
const assunto = PREFIXO + ' - Hapvida - Comissoes a resgatar - ' + hoje;

return [{ json: { assunto, corpoHtml, novos_count: novos.length, atrasados_count: atrasados.length } }];

