// P36 (21/10/2026): avisa o André quando a checagem não consegue entrar num código.
// Erros "detalhe:" (lote sem relatório sintético etc.) não são falha de login: ficam de fora.
const data = $input.first().json;
const falhas = [];
if (data.error) falhas.push({ codigo: 'todos', erro: 'a checagem (/run) falhou: ' + (data.error.message || JSON.stringify(data.error)) });
for (const e of (data.erros || [])) {
  if (!String(e.erro || '').startsWith('detalhe:')) falhas.push(e);
}
const linhas = falhas.map((f) => '<li><b>' + f.codigo + '</b>' + (f.ano ? ' (' + f.ano + ')' : '') + ': ' + String(f.erro).slice(0, 300) + '</li>').join('');
const hoje = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });
return [{ json: {
  falhas_count: falhas.length,
  assunto: 'Comissão Hapvida: login falhou em ' + falhas.map((f) => f.codigo).join(', ') + ' (' + hoje + ')',
  corpoHtml: '<p>A checagem diária de comissões não conseguiu entrar nestes códigos, e os pedidos deles não foram atualizados hoje:</p><ul>' + linhas + '</ul><p>Se a senha mudou, atualize no Bitwarden.</p>',
} }];
